// Native-only fixture generator. No part of this target ships in the managed library.
#include <windows.h>
#include <bcrypt.h>
#include <blosc.h>
#include <blosclz.h>
#include <shuffle.h>
#include <snappy.h>
#include <algorithm>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
using Bytes=std::vector<uint8_t>;
std::string hex(const Bytes& bytes){ static const char* digits="0123456789abcdef";std::string result;result.reserve(bytes.size()*2);for(auto b:bytes){result+=digits[b>>4];result+=digits[b&15];}return result;}
std::string digest(const Bytes& bytes){BCRYPT_ALG_HANDLE algorithm=nullptr;BCRYPT_HASH_HANDLE hash=nullptr;Bytes result(32);if(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0||BCryptCreateHash(algorithm,&hash,nullptr,0,nullptr,0,0)<0||BCryptHashData(hash,const_cast<PUCHAR>(bytes.data()),ULONG(bytes.size()),0)<0||BCryptFinishHash(hash,result.data(),32,0)<0)throw std::runtime_error("SHA256 failed");BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(algorithm,0);return hex(result);}
std::ofstream output;int emitted=0;
void emit(const std::string& name,const std::string& kind,const Bytes& packed,const Bytes& raw,int type=1){if(emitted++)output<<",\n";output<<"{\"name\":\""<<name<<"\",\"kind\":\""<<kind<<"\",\"typeSize\":"<<type<<",\"length\":"<<raw.size()<<",\"sha256\":\""<<digest(raw)<<"\",\"input\":\""<<hex(packed)<<"\"}";}
Bytes pattern(size_t size,int kind){Bytes result(size);uint32_t random=0x12345678;for(size_t i=0;i<size;++i){random=random*1664525+1013904223;result[i]=kind==0?uint8_t(i%13):kind==1?uint8_t((i/64)%7):kind==2?uint8_t(random>>24):uint8_t(i%1024<1000?42:random>>24);}return result;}
void rawCheck(const std::string& name,const std::string& kind,const Bytes& packed,const Bytes& expected){Bytes decoded(expected.size());if(kind=="blosclz"){int n=blosclz_decompress(packed.data(),int(packed.size()),decoded.data(),int(decoded.size()));if(n!=decoded.size())throw std::runtime_error("BloscLZ raw decode failed: "+name);}else{size_t size=0;if(!snappy::GetUncompressedLength((const char*)packed.data(),packed.size(),&size)||size!=decoded.size()||!snappy::RawUncompress((const char*)packed.data(),packed.size(),(char*)decoded.data()))throw std::runtime_error("Snappy raw decode failed: "+name);}if(decoded!=expected)throw std::runtime_error("Raw native bytes differ: "+name);emit(name,kind,packed,decoded);}
void varint(Bytes& out,uint32_t value){do{uint8_t byte=value&127;value>>=7;out.push_back(byte|(value?128:0));}while(value);}
void little(Bytes& out,uint32_t value,int width){for(int i=0;i<width;++i)out.push_back(uint8_t(value>>(8*i)));}
void snappyLiteral(Bytes& out,const Bytes& raw,int width=0){size_t len=raw.size();if(!len)return;if(width==0&&len<=60)out.push_back(uint8_t((len-1)*4));else{uint32_t n=uint32_t(len-1);if(!width){width=1;while(width<4&&(n>>(width*8)))++width;}out.push_back(uint8_t((59+width)*4));little(out,n,width);}out.insert(out.end(),raw.begin(),raw.end());}
void bloscLiterals(Bytes& out,const Bytes& raw){for(size_t pos=0;pos<raw.size();){size_t n=std::min<size_t>(32,raw.size()-pos);out.push_back(uint8_t(n-1));out.insert(out.end(),raw.begin()+pos,raw.begin()+pos+n);pos+=n;}}
void rawCases(){
 for(int kind=0;kind<4;++kind)for(int size:{16,31,32,33,60,61,128,257,1024,8193,70000}){Bytes raw=pattern(size,kind);std::string name="pattern-"+std::to_string(kind)+"-"+std::to_string(size);std::string compressed;snappy::Compress((const char*)raw.data(),raw.size(),&compressed);rawCheck("snappy-"+name,"snappy",Bytes(compressed.begin(),compressed.end()),raw);for(int level:{1,5,9}){Bytes packed(size*2+256);int n=blosclz_compress(level,raw.data(),size,packed.data(),int(packed.size()),1);if(n>0){packed.resize(n);rawCheck("blosclz-"+name+"-"+std::to_string(level),"blosclz",packed,raw);}}}
 rawCheck("snappy-empty","snappy",Bytes{0},Bytes{});
 for(int size:{1,2,59,60,61,255,256,257,65535,65536,65537})for(int width:{0,4}){auto raw=pattern(size,2);Bytes packed;varint(packed,size);snappyLiteral(packed,raw,width);rawCheck("snappy-literal-"+std::to_string(size)+"-"+std::to_string(width),"snappy",packed,raw);}
 for(int offset:{1,2,7,255,2047,2048,65535,65536,70000})for(int width:{1,2,4})for(int length:{4,11,64}){if(width==1&&(offset>2047||length>11))continue;if(width==2&&offset>65535)continue;Bytes raw=pattern(offset,2),packed;varint(packed,offset+length);snappyLiteral(packed,raw);if(width==1){packed.push_back(uint8_t(1+((length-4)<<2)+((offset>>8)<<5)));packed.push_back(offset&255);}else{packed.push_back(uint8_t((width==2?2:3)+((length-1)<<2)));little(packed,offset,width);}for(int i=0;i<length;++i)raw.push_back(raw[raw.size()-offset]);rawCheck("snappy-copy-"+std::to_string(offset)+"-"+std::to_string(width)+"-"+std::to_string(length),"snappy",packed,raw);}
 for(int offset:{1,2,7,255,8191,8192,65536,73727})for(int length:{3,8,9,264,1024}){Bytes raw=pattern(offset,2),packed;bloscLiterals(packed,raw);int distance=offset-1;int control=(std::min(length-2,7)<<5)|(offset>=8192?31:(distance>>8));packed.push_back(control);if(length>=9){int more=length-9;while(more>=255){packed.push_back(255);more-=255;}packed.push_back(more);}if(offset>=8192){packed.push_back(255);int farOffset=offset-8192;packed.push_back(farOffset>>8);packed.push_back(farOffset&255);}else packed.push_back(distance&255);for(int i=0;i<length;++i)raw.push_back(raw[raw.size()-offset]);packed.push_back(0);packed.push_back(177);raw.push_back(177);rawCheck("blosclz-copy-"+std::to_string(offset)+"-"+std::to_string(length),"blosclz",packed,raw);}
}
void filters(){for(int type:{1,2,3,4,8,12,16,24,255})for(int elements:{0,1,7,8,9,15,16,127,128,129})for(int tail:{0,1}){if(tail>=type)continue;auto raw=pattern(type*elements+tail,2);Bytes packed(raw.size()),decoded(raw.size()),temp(raw.size());blosc_internal_bitshuffle(type,raw.size(),raw.data(),packed.data(),temp.data());blosc_internal_bitunshuffle(type,raw.size(),packed.data(),decoded.data(),temp.data());if(raw!=decoded)throw std::runtime_error("Native filter mismatch");emit("bitshuffle-"+std::to_string(type)+"-"+std::to_string(elements)+"-"+std::to_string(tail),"bitshuffle",packed,decoded,type);}}
void frames(){for(const char* codec:{"blosclz","lz4","snappy","zlib"})for(int filter:{0,1,2})for(int type:{1,3,4,12})for(int size:{2048,2051,8192})for(int split:{BLOSC_ALWAYS_SPLIT,BLOSC_NEVER_SPLIT}){auto raw=pattern(size,0);Bytes packed(size+BLOSC_MAX_OVERHEAD),decoded(size);blosc_set_splitmode(split);int n=blosc_compress_ctx(9,filter,type,size,raw.data(),packed.data(),packed.size(),codec,512,1);if(n<=0)throw std::runtime_error("Native frame encode failed");packed.resize(n);if(blosc_decompress_ctx(packed.data(),decoded.data(),decoded.size(),1)!=size||decoded!=raw)throw std::runtime_error("Native frame decode mismatch");std::string name=std::string(codec)+"-frame-"+std::to_string(filter)+"-"+std::to_string(type)+"-"+std::to_string(size)+"-"+std::to_string(split);emit(name,"frame",packed,decoded,type);if(filter==1&&type>1){packed[2]|=4;if(blosc_decompress_ctx(packed.data(),decoded.data(),decoded.size(),1)!=size||decoded!=raw)throw std::runtime_error("Native combined filter mismatch");emit(name+"-both-filters","frame",packed,decoded,type);}}blosc_set_splitmode(BLOSC_FORWARD_COMPAT_SPLIT);}
void compatibility(const fs::path& directory){for(const auto& file:fs::directory_iterator(directory)){auto name=file.path().filename().string();if(file.path().extension()!=".cdata"||(name.find("snappy")==std::string::npos&&name.find("blosclz")==std::string::npos&&name.find("bitshuffle")==std::string::npos))continue;std::ifstream in(file.path(),std::ios::binary);Bytes packed((std::istreambuf_iterator<char>(in)),{});size_t length,compressed,block;blosc_cbuffer_sizes(packed.data(),&length,&compressed,&block);if(length>16*1024*1024||compressed!=packed.size())throw std::runtime_error("Invalid compatibility fixture");Bytes decoded(length);if(blosc_decompress_ctx(packed.data(),decoded.data(),decoded.size(),1)!=length)throw std::runtime_error("Compatibility decode failed: "+name);emit("compat-"+name,"frame",packed,decoded);}}
int main(int argc,char** argv){try{if(argc!=3)throw std::runtime_error("usage: codec-reference output.json c-blosc-compat-directory");blosc_init();std::cout<<blosc_list_compressors()<<'\n';output.open(std::string(argv[1])+".tmp");output<<"[\n";rawCases();filters();frames();compatibility(argv[2]);output<<"\n]\n";output.close();if(!MoveFileExW(fs::path(std::string(argv[1])+".tmp").c_str(),fs::path(argv[1]).c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Could not publish verified fixture");blosc_destroy();std::cout<<"Verified "<<emitted<<" native codec fixtures\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
